import{_ as t,o as a,c as r,aF as o}from"./chunks/framework.CNkxH4QO.js";const u=JSON.parse('{"title":"krawler-awc","description":"Job scraping METAR and TAF data from the Aviation Weather Center.","frontmatter":{"title":"krawler-awc","description":"Job scraping METAR and TAF data from the Aviation Weather Center."},"headers":[],"relativePath":"packages/krawler-awc/index.md","filePath":"packages/krawler-awc/index.md"}'),d={name:"packages/krawler-awc/index.md"};function i(n,e,s,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="krawler-awc" tabindex="-1">krawler-awc <a class="header-anchor" href="#krawler-awc" aria-label="Permalink to &quot;krawler-awc&quot;">​</a></h1><p><em>Job scraping METAR and TAF data from the Aviation Weather Center.</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <strong>krawler-awc</strong> jobs allow to scrape data using the <a href="https://aviationweather.gov/data/api/" target="_blank" rel="noreferrer">api</a> provided by the <strong>Aviation Weather Center</strong>.</p><p>The downloaded data are stored within a <a href="https://www.mongodb.com/" target="_blank" rel="noreferrer">MongoDB</a> database and more precisely in 3 collections:</p><ul><li><code>awc-metars</code> that stores the <strong>METAR</strong> data</li><li><code>awc-tafs</code> that stores the <strong>TAF</strong> data</li><li><code>awc-stations</code> that stores the stations data</li></ul><p>All records are stored in <a href="https://fr.wikipedia.org/wiki/GeoJSON" target="_blank" rel="noreferrer">GeoJson</a> format.</p><p>The job is executed according a specific cron expression. By default, every hours.</p><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to &quot;Implementation&quot;">​</a></h2><p>As far as possible, jobs use the <a href="https://aviationweather.gov/data/api/#cache" target="_blank" rel="noreferrer">cache files</a>.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="stations" tabindex="-1">Stations <a class="header-anchor" href="#stations" aria-label="Permalink to &quot;Stations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_URL</code></td><td>The mongoDB database URL. The default value is <code>mongodb://127.0.0.1:27017/awc</code></td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><h3 id="metars-tafs" tabindex="-1">metars-tafs <a class="header-anchor" href="#metars-tafs" aria-label="Permalink to &quot;metars-tafs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>DATA</code></td><td>The type of weather dataset to process (metars, tafs). The default value is <code>metars</code>.</td></tr><tr><td><code>DB_URL</code></td><td>The mongoDB database URL. The default value is <code>mongodb://127.0.0.1:27017/awc</code></td></tr><tr><td><code>TTL</code></td><td>The data time to live. It must be expressed in seconds and the default value is <code>2592000</code> (30 days)</td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table>',15)])])}const f=t(d,[["render",i]]);export{u as __pageData,f as default};
